mapper.insert:
INSERT INTO PRODUCT (
    PRODUCT_ID
    ,PRODUCT_NAME
    ,PRODUCT_DES
    ,PRODUCT_PRICE
    ,PRODUCT_QTY
    ,PRODUCT_CODE
    ,MEM_ID
    ,MEM_CODE
    ,PRODUCT_PICTURE
) VALUES (

    (SELECT TO_CHAR(SYSDATE,'YYYYMMDDHHSS') || #{product_name} FROM DUAL)
    ,#{product_name}
    ,#{product_des}
    ,#{product_price}
    ,#{product_qty}
    ,#{product_code}
    ,#{memId}
    ,#{memCode}
    ,#{product_picture}
)
